BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (237::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '6435a87440e307675ae8d4ef47021ed4bdad8f5cbbb44b2bb86c6ab9fd310769'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe sabe, pero califica pesado. Los quices son muy realizables si se estudia pero si es un poco aburrido. Los exámenes son volados entonces hay que tener cuidado y llevarlo al día. Califica medio justo pero a veces es rudo. No es tan malo. Muchas clases son asincrónicas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6ce4cacad8acae84dcc684d35a2fe9cdae93be4d531e00588a11c4051dd59a19'::TEXT, ARRAY[1726]::BIGINT[]),
    (237::BIGINT, 'Hace clases cada 15 días y quizzes virtuales. Si usted es autodidacta y quiere una clase que no quite mucho tiempo, él es ideal. Pero no sabe explicar y se enreda solo, así que no espere aprender de él.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'b6d10ea16a4f794a77d88618560000898d7ee0121a5af29486ad6e52044f48e8'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'El curso no es como lo pintan, no es para nada complicado. El profe es buena gente y explica bien, el material de la catedra es muy útil. Si lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'fe2af46aac708445a00d3beff6a4fac039ecdb34d7b41421b47deec1e226ad61'::TEXT, ARRAY[1726]::BIGINT[]),
    (237::BIGINT, 'Siento que si estudio lo suficiente yo también podría ser profesor del tec, si tiene la oportunidad de matricular con él, desaprovéchela completamente. Es más inútil que la liga en finales, realmente si dieran un título de incompetencia, él no lo ganaría porque no llegaría a la gala.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-15T00:00:00+00:00'::TIMESTAMPTZ, '5d74d4aff5b69862f2d597d98c06f9ceab6b8d69ace6c602d63a3fa1f5b1e853'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'Es muy buen profesor, lo importante es llevar la materia al día, hacer las guías e ir a clase. Es muy importante ir a clase y poner atención, para el profe es de relevancia. El curso no es difícil si se estudia bien con exámenes viejos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '9ed7149b757aa3cbda3c528acf872188bd138457653d71922c102f92d9889a21'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Julio es increíble. Enseña bastante bien, evalúa muy fácil y de verdad se preocupa que uno aprenda, pero sobre todo que el curso no sea una carga. Hágale las consultas que necesite y de verdad aproveche las clases con el, es genial.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c373b024ec244112c249169be3a1fd64e80e0a272c7592f265a59efcd6ac44b2'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-01-27T00:00:00+00:00'::TIMESTAMPTZ, '094d87501cc7b4e329487c4f2893d94ad1a9ac139e491001ba2ca8e9f28cec4b'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En general esta bien, la materia no es tan difícil como la pintan, el problema es la evaluación "Binaria", es decir, o todo bueno o todo malo, no hay puntos intermedios :/'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '44e278d6500ef12ef382452b70d0274d4f6c1c3aa43abf00080c703a77fc0b55'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Daba el curso con pereza y era muy desordenado. Es muy buena persona, pero solo ayuda cuando quiere'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b9dd941e298495a6ae91bcf5c7d915efb889388ee2fbb278e938366f1f6a2c28'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Mi testimonio acerca del profesor, es que me gustó tanto el curso que lo había llevado 2 veces antes de llevar con él, sinceramente, la mejor fue con Julio, el curso es cátedrado y el profe cumple la función de resolver las dudas que uno tenga y dar un resumen con justamente lo que uno necesita'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd4b3a30e9fe574e5016b095f5970c34bf5c2781be0ec18329c5356ac85005233'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe siempre está dispuesto a ayudar, explica decente, siempre trata de que todo quede claro, hace ejercicios en clase. Lo malo es que es algo desorganizado y da notas hasta el final'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b577418231c6afcce288b3a0289977e7884625c17d7e1cebdb261a4425fe1a23'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Basicamente el curso es dificil, la unica forma de pasar es estudiar del libro y llevar la materia al dia, el profe casi no explica hace solo ejercicios y hace como 10 quiz y al final deja los 6 mas altos para ayudar. Hay que esforzarse bastante, no depende del profe.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3bb79cf7b000105dcd57f0f0b5701e6d2a1d4239fb88d9835e5b80ed60e27bb7'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'Hay que ser un poco autodidacta ya que en las clases básicamente solo se resuelven ejercicios y la mayoría de veces se trabajan profesor-estudiante. Si usted no lleva el estudio al día lo va a pasar muy mal, los quices son fáciles pero él asistente califica muy duro. Recomiendo asistir a consulta.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '8b95076e000da19c886c0a147106f0cbeda53c54c683f06cc1d26a0374a42e12'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Como profesor está bien y hay que ser un poco autodidacta pero hace más digerible el curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '8e3e46c37c67a408f3c4fa14e0aca3876b66d4a80e15fc32d5713e4448c38365'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e9faae37e44606a52120be6a22ff2179d1773a254d6d52d9b7c826de61295bdd'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Las clases son resolver los ejercicios recomendados por la cátedra por lo que casi no ayudan para los exámenes, sus explicaciones en veces son muy confusas, por lo que a uno le toca ser prácticamente autodidacta. Los quices que hace son sorpresa pero son ejercicios del libro.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'fb2f6ee278d93d92665f0eb16504309391b1d2c3b57d2044548827fe2e6d0cd6'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'Empieza a explicar bien, pero cuando se le pregunta algo se enreda todo y confunde. Vuelve a hacer los ejercicios que ya estan resueltos en la catedra lo cual no ayuda en nada, hace quiz sorpresa lo cual afecta mucho. No lo recomiendo para nada, da solo como una hora y media de clase super rapido'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '581a2c1c4892060899d5616a73f4f86986232f4f8c8106e8732fdcc9fc3b98a9'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'El curso es una vasura, pero el profe lo hace mas ameno, siempre intenta explicar todo en clase a la diferencia de catedra que no sirve para nada, ayuda en los quices y proyectos (son los mas faciles que vi en todo el curso).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ef2c70b45786dd596fba5e4111752c521344ecdc820293ca25df4eb6246ee7f0'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Este es un curso para ser muy autodidacta pero la realidad es que las clases de este profe no son para nada buenas. Quices sorpresa con ejercicios medio complejos y ejercicios de práctica vistos por encima, con muy poca explicación teórica. Suele ayudar con quices extra pero no lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '12140b13a91f62a04b1f411be45f3d869074a8974153bc0932262df6e12a080c'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'El profe ayuda bastante y califica bastante suave, sin embargo hay que ser bastante autodidacta con el curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c3c18e76957ce1c73c76f6d0ebc27fd80662b6fd8facbcfe1280b5af454f93fa'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe ayuda mucho, al final de 60 quedamos 10, y nos ayudo a todos, con quices y proyectos faciles, se nota que le interesa que uno entienda, hay que ir a una que otra consulta para hacerse denotar entre tantos y obtener la ayuta, pero es muy buena nota, y una excelente persona.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, '4b81530b8dc7873cbb4f2aeae9a364bce45398963eb6debd1cb2186caf411ab2'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Un curso difícil y este profe lo complica más. Los quices son sorpresa y ni se sabe cuál tema entra, y para peores pone ejercicios difíciles. En la clase no da la materia, solo hace ejercicios de práctica. Como persona es excelente, pero recomiendo atrasar el curso antes que matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-04T00:00:00+00:00'::TIMESTAMPTZ, '5be1ef05095a2accf9257fa99109c907edcc6a3e710f4fa8bf2f7f0edfc3f309'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'El curso es bastante dificil. El profe no da la materia, las clases son de repaso, así que deberá ser autodidacta. El profe es bueno sí, o por lo menos las cosas que evalúa las hace de forma suave. Le recomiendo que vaya mucho a consulta, a la que sacar cita puede ser más dificil que para la CCSS.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a646500514ed95344542dc20b2560583b5007346849b812ad6de573b7a5a7595'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Sus trabajos en clase son bastante sencillos y en grupos, sin embargo sus clases son solamente de resolución de ejercicios y aclaración de dudas. Hay un examen bastante duro que no lo revisa él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '955bfa784ae1e150f7aa1b84f3ff6696a1d93fbdfeb0e8796ab62427a2eb94d6'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En virtual las clases fueron nada más de aclaración y resolución grupal de ejercicios, hay que pasar a pura cátedra. El profe explica bien y es muy ordenado para consultas. No es estricto, es comprensivo y empático con el estudiante, pero no espere mucho de sus clases. Cumple con lo que se espera.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '02f9c3a2a26d9ffb6c01cc9e02a93968f177c126b1613d62397c11df4c5b6964'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe es buena gente y las evaluaciones son hacer ejercicios grupales en clase, pero no es tan malo, si usted y su grupo estudian.Yo lo recomiendo, porque muchos compañeros que estaban con otros profes decían que hacían quices individuales súper difíciles, a cambio de la otra manera tenes apoyo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'a0cbcd24aea0cf534ee38b6892c857570213ac405f26d9602e6c97573df771db'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Para verano no lo recomiendo, no supo como dividir las evaluaciones del curso y toda la nota para aprobar la dejo en 4 evaluaciones, no se aprende nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2022-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'fec33c5863fe62e161cce4398bdcc190012694db538ad6ac96139ff2d2ea9664'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Estática es un curso difícil. El profe NO da clase, usted se la debe jugar a pura cátedra, pero todas las semanas tiene trabajo grupal. Asegúrese de conseguir esos trabajos con alguien que llevara ese curso con el anteriormente. Consiga un buen grupo para el proyecto. Buena opción para matricular.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'ef84b72ff5a3cda8035057f831424550e191efda206504255cbeaab8a9cca95b'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Hace exámenes cortos todas las clases pero son en grupos y se vuelven un poco más fáciles. Es el mejor profe con el que llevar este curso en mi opinión, ya que ayuda si alguna duda y ayuda un poco en los exámenes cortos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'c68ba95d611b267213369e344c3e06679809c74621fb2c77d3e54ee51fad4ed1'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En estática no hay mucho de donde escoger pero el es buena opción. No es estricto revisando trabajos y es compresivo. Eso si, la mayoría de las evaluaciones son grupales así que hay que conseguir un buen grupo. Además se debe estudiar el material de cátedra antes de ir a la clase'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'f5ea7332696cc2f5415ed11ce40943908c072e50a0b10264809d008eacc0da94'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Buen profe, en estática hay poco de donde escoger y él podría ser una buena opción debido a que es comprensivo, atento a dudas y consultas, evalúa suave. Pero las clases no son las mejores y debe preparase para estudiar por aparte.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '9655dc7852217d56dc4932bd461fce216360fef83e63eaac73e27e6025bbcd51'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Siento que cumple en explicación, no excelente pero cumple. Siempre trata de aclarar las dudas que uno tenga, ya sea en clase o fuera. Es comprensivo con los estudiantes. Estática es todo por catedra, por lo que no lo veo mala opción.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '6102bb34191ee2103ad5bd29209235dc4c11ecc370090354b30de4cf1f463c69'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Como profe es regular pero el mae ayuda muchísimo , al menos virtualmente.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'a64139315436ccc8bebfb9c796b92808519f17460d1d91450cd3b62c13ab37b7'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profesor es regular, con el semestre virtual casi todo se hacia mediante la cátedra y las evaluaciones eran rudas, las rubricas no eran claras y no daban suficiente tiempo para exámenes. No sé si lo recomendaría, al final ayudo a varios a no tener que ir a repo y a ir a repo si se iban a quedar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'cc1da3a59ebd38ee0dff56b9194591bad7f802060e48ed18fe901d17cb673f8b'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En modalidad virtual, la mayoría de la materia fue brindada por la Cátedra, por lo que las clases sincrónicas tampoco apoyaban mucho, pero de igual manera se notaba que no le importaba mucho dar apoyo extra a los estudiantes. En conclusión, es un cero a la izquierda si estudia por sí solo.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'ebd2e390697e902c45acf23eea984c7963b0201aabba0c04aa3d16e0cfa05cc8'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En virtual él solo da una repasada a los resumenes que da la cátedra. Atiende bien las dudas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '1614f6b5c4dff25a7e36c6a3db1b8eea45ba041656365480d3175aaf45b8654a'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'No sé si sea por la modalidad más bien de la cátedra que no le permite dar clases como debe ser, no es suficiente lo que da por semana en su clase sincrónica para lo que exige un curso tan difícil.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'c92c0fd77754a689b622f4c968c254b2db320aadbd551a7842559cbcff5d35e8'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Virtual. El profe es bueno. De manera virtual debería acomodarse mejor ya que explica lo básico. La clase la hace corta. El curso es pesado y la cátedra manda tareas largas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'b1689f94149a22b4897978c6396594ba5baedea2448259ce5f38a18b34e18047'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Me parece que es buen profesor y que no es su culpa que estática sea bastante difícil. La materia no es ninguna broma pero este profesor va a intentar ayudar a pasar a la máxima cantidad de estudiantes comprometidos'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '56ccaa706a0f32dfbcd498b632a2f55f2df0d4db98a5dbf0b69a254235614088'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En el semestre virtual, solo daba 1 hora de consultas a la semana, el resto uno se tenía que volver autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c42cd282f328cc4be7b8db3fe855630fa7c7ab958c22d1c8d15604ecfd9e7818'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Excelente profesor, da buena cantidad de consultas virtuales. Siempre responde todas las preguntas con toda tranquilidad sin importar nada. Recomendadísimo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'a08ba31c5d27fa0f0bb51367e7202dcf9cee5245e6177313e9eca35c3b3cf933'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe no es malo sin embargo, la cátedra de estática es un chiste, exámenes de 45%, videos poco claros explicando la materia y metodología de evaluación en parciales dan ganas de llorar. El profe atiende cualquier duda que tenga solo que por encima, así que llegue con una noción de que trata.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '694da9af3377e2d71dd0985f1846dbd1f063c66aa1bbadd7a9fddfa9261360e7'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'La cátedra tomó decisiones perjudiciales para todos, pero sí hicieron videos para explicar la materia, hay que estudiar del libro, olvidese de pasar el curso si no planea estudiar solo y solo quejarse. PRACTIQUE Y VAYA A CONSULTA, a mí eso me salvó, el profe siempre lo toma en cuenta'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '71144d0f0d91c3cfb192f8a9112840c9cf62bef0697a0fb20a3cfa8c6fb820cd'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En la modalidad virtual la cátedra uso una evaluación de solo dos examines de 45% cada uno. El profe solo da clases un día por semana y solo para despejar dudas, toca aprender del libro.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'b2492e0d13ac900ac13f1b76b8e2de5fa94e207b1273a5b6501b42f7b2ca0037'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Ayuda mucho en consulta, es importante ir, porque da clase solo una vez por semana para resolver 1 o 2 ejemplos en una hora. A veces se confunde explicando el ejercicio, pero siempre quiere ayudar. Hay que estudiar mucho del libro en este curso, la evaluación fue durilla, pero es pasable totalmente.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2e4030da40056b80e64feea95a2a3c8bc493c4d5fb27a8458776d74b64fb8b8'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'En modalidad virtual es un completo vago, solo da clases si uno le lleva dudas del libro, de lo contrario no enseña nada. Igual es mejor que muchos de los otros profes. Además la cátedra del curso es lo más injusto que encontrado en el TEC. Lo recomiendo porque da igual lo que escoja, suerte.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '84b1926b260dfb7e7e1de79bf62ca64080d91e4f4c2d413e7d13903a569ec89a'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'No hay mucho de donde escoger ya que es de los mejores profes que hay, pero en modalidad virtual no hace el esfuerzo para que los estudiantes aprendan. Da una clase por semana que por lo general medio explica 1 o 2 ejemplos. Dejando por fuera que la cátedra es una completa basura.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '01d9ada480c0a867983f7e1975af2dfe024e4957c34c5bea6a182566e5400fd9'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Este profesor es un vagazo, es el coordinador de cátedra de estática, y es de las peores cátedras, después de la pandemia puso una evaluación injusta de dos exámenes de 45%, casi nadie pasó este semestre virtual, aún así es lo menos malo de estática. Mediocre'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '9b9a4e8e35d942852f2972f9183328985118cf3b63b7a6c108361b10af15f3b5'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Trata de explicar muy claro y que el estudiante aprenda. No obstante, la materia requiere de mucha practica. Pero es un profe muy pura vida. Volvería a matricular con el.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'a33c39d59b84668f122469a9ddc2d82b7cbb85194357ecabbc7be2ab964b4d37'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Uno de los mejores profesores que he tenido en el TEC, siempre dispuesto a ayudar a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c2b6f06594b529e2c73c2b65de8cdd735f42e81bbb21ee5b8872cbd6af5e06e8'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Es de lo mejorcito para el curso, da ejemplos con un buen nivel en clase (aunque no siempre se terminan), los quices son bastante sencillos -lo cual es sumamente importante, y atiende las dudas que uno tenga. El proyecto lo califica suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '330a283ab7f5b4ea7fff582319349e12cae111d6e3e2c0251b06a59596ee7178'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El curso es un poco complicado, pero el profe deja los ejercicios mas fáciles para los quices y en el proyecto califica muy al suave, esto hace tener la posibilidad de pasar aunque se tengan exámenes bajos.Debe estudiar del libro, ya que aveces no completa los ejercicios al 100%'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '3ae772937f6422b330535fa4f3a9370204a270e35e9d94e78b505e9798a55678'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Los quices son sencillos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '4af99fcaae27946b93c56195d1fdf04a701b75debb3459eeecf383b72d2068d8'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'De lo mejor para estática, hay que ser un poco autodidacta pero en general es muy bueno.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-07T00:00:00+00:00'::TIMESTAMPTZ, '09dc7fc07c037107f0cc440d81f55c0cbee082eca538e5ae740c03fefb8cbf94'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Alarga demasiado la explicación de los temas, cayendo en redundancia y haciendo la clase aburrida. Escribe muy pequeño. A veces no completa los ejercicios al 100%.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, '4f38c345ae56cf48cba8fc4091485332cd9913140d39d0391f7bd760cfa28e93'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Muy buen profesor. Hay que estudiar del libro (igual que cualquier profesor). Quices fáciles y comprende al estudiante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f16e59c3bb2ebb0cd2e23e6f7cdd1ea992d9ded982585d6faa82b1b4d6f9155a'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Hay que ser autodidacta, no explica nada de la materia, solo llega a leer la presentación que es lo mismo que dice el libro y dura 1 semana completa haciendo un ejercicio fácil y ni siquiera explica los pasos, todo hay que estudiarlo del libro. NUNCA lleva la clase preparada llega a improvisar'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ac1496cd86d3d5676b4e2c3ee90fee99c98f64f68cc22ca5a0ded7ee22188c35'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Buen profe, explica las veces que sea necesario.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'bd056d613601d45a80f88f56ff02b77d0a1c8f4bc119b0f64163b479633c3a84'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8d58c7940a8494d7246db3870d628451c04532732cc163dcdb1dcf147169811c'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Sea autodidacta porque con lo que él explica no es suficiente. Tarda mucho resolviendo un ejercicio en la pizarra y comete errores. Los quices son normales y dura mucho para entregar las tareas y quices. Es buena gente'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b2d95cdd6fa0bf759b92c5a7a2d500b2ea44c889630c997a2b6f3e21d826c4bc'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'El profe es buena nota, pero dura una semana haciendo UN ejercicio (de los fáciles), se nota que llega a improvisar la clase y la clase se hace larga. Hace quices normales.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '91fe318796d5b3e84230bff4103e91a4a0ad0a8dacac1718be17ee3a47988973'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Para ser profe de mante es de los mejores que hay, no hay mucho de donde escoger. El mae es buena gente, un poco vago, pero es el único que he visto que intentara ayudar a mejorar un poco la cátedra de estática'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6ba109c5af09a4538d93d2fa015d992ad57ca07d13a92d9d928b1d40794a8930'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Es de los menos malos para estática. Como persona se ve buena gente pero en clases dura como 1 semana haciendo un ejercicio (de los fáciles). Los quices empiezan muy fácil y ya después se vuelven difíciles. Si quiere pasar el curso, vaya a las tutorías, ahí sí aprende.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '902dc770fb26428023474aefea87b6937d515b593bbc84caf005ea177648c876'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Profesor muy flojito, le recomiendo que vaya a tutorías para que vea el verdadero nivel de problemas que le van a salir en el examen'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '0fe3492d6f9bc8d2dd244e14ee4d85b791994bc41b555f60ecb87f31991823c2'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Como persona se ve muy amable, sin embargo el profe era la primera vez que daba estática y no tenía como muchísimo dominio en los temas, lee presentaciones, los quices no son sencillos como dicen y no "regala" la nota, hay que estudiar de parte de uno para pasar ese curso. Pero no hay mucha opcion'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '834d028795e7e7561f6f21c58fdf68c81506026d1094dfb836e74a056b30349d'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Explica regular pero tampoco hay muchas opciones en estática, entonces es lo mejorcito. Hace quices facilones y ayuda bastante. Es muy buena gente'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '05fe28a1a2bb3fea7eb94d30d64bfe674fd12da0736d9299d87c7daab8b5fec6'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Es buena nota, pero no es buen profe; casi no hace ejercicios en clase, "nos deja pensarlo" pero al final nunca le da tiempo de resolver el ejercicio.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a7fc42ae4ffc67b18814a06ece10d56c12528059af0d94abf91466b8358204db'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Profesor malo, no es bueno para explicar, hay ejercicios que ni él sabe resolver, es buena gente pero no lo recomiendo como profesor'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-25T00:00:00+00:00'::TIMESTAMPTZ, '976e26b2b23a4913332f0798f82b2060aa797dc060000679de585118911ee111'::TEXT, ARRAY[636, 1726]::BIGINT[]),
    (237::BIGINT, 'Definitivamente un profe excelente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2f8cf9318c4bb9f76ee2de01f97c6db4a849feef715e7de6c2ec4133b20dbd3d'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'El profe es super buena nota. Siempre atiende cualquier duda y de verdad se preocupa por que los estudiantes aprendan y salgan bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-08-03T00:00:00+00:00'::TIMESTAMPTZ, '8c967157e415b233608f437c9ff68815b3b7ef99cdca6f5a578ca660518e418d'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'MUY TRANQUILO NO SE ESTRESA EL CURSO NO SE HACE NADA PESADO'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-26T00:00:00+00:00'::TIMESTAMPTZ, '001e96add6ad8faf9be07a7eaccfe19da225cbf322cc0634d905b04786532492'::TEXT, ARRAY[610]::BIGINT[]),
    (237::BIGINT, 'Por mucho el peor profe. No conoce el tema, califica duro y los quices dificiles'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5ef5fea15d7e7b639edcd6930b44dad7509787a65929dbc907973c2f2465d3ad'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'No explica bien. Hace ejercicios resueltos y muy fáciles. No repone clases perdidas. Los quices no son fáciles aunque él diga lo contrario. No lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2206fa5370b4f522caab0f5cea90dfc726f3f032d02c35093eb8fed1799d59aa'::TEXT, ARRAY[945]::BIGINT[]),
    (237::BIGINT, 'No explica muy bien. Varios de los ejercicios que resuelve ya vienen resueltos en el libro. Las consultas son de 15 mins. y la verdad no sabe mucho o si uno le pone un problema difícil probablemente le da indicios de cómo se hace, pero él no lo puede resolver... Ayuda si uno participa constantemente'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4960b9234629e9f0d775a532133d001a6603058288d19b51386c7f792314a57f'::TEXT, ARRAY[945]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
